    window.addEventListener('keyup', e => {
      if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
      if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
    });
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    const rollAxis = new THREE.Vector3();
    const deltaQuat = new THREE.Quaternion();
    let lastTime = performance.now();

    function animate(t) {
      requestAnimationFrame(animate);
      const dt = Math.min((t - lastTime) / 1000, 0.05);
      lastTime = t;

      if (isPlaying) {
        const speed = Math.min(88, 32 + Math.abs(ball.position.z) / 110);
        ballVel.z = -speed;
        let steer = (keys.left ? -1 : 0) + (keys.right ? 1 : 0);
        ballVel.x += (steer * 26 - ballVel.x) * Math.min(1, dt * 15);
        ballVel.y += -58 * dt;

        const next = ball.position.clone().addScaledVector(ballVel, dt);
        let onTile = false;
        let groundY = -999;

        for (const tile of tiles) {
          if (Math.abs(tile.z - next.z) > tile.length + 12) continue;
          const relX = next.x - tile.x;
          const relZ = next.z - tile.z;
          if (Math.abs(relX) <= tile.width / 2 && Math.abs(relZ) <= tile.length / 2) {
            const sY = tile.y - (relZ * Math.tan(tile.pitch)) + 0.7 + 0.85;
            if (next.y <= sY + 0.45 && next.y >= sY - 2.8) {
              groundY = sY;
              onTile = true;
              break;
            }
          }
        }

        if (onTile) {
          next.y = groundY;
          ballVel.y = 0;
        }
        ball.position.copy(next);

        // Realistic Quaternion Rolling
        const moveDistX = ballVel.x * dt;
        const moveDistZ = ballVel.z * dt;
        const moveDist = Math.hypot(moveDistX, moveDistZ);
        if (moveDist > 0.0001) {
          rollAxis.set(-moveDistZ, 0, moveDistX).normalize();
          deltaQuat.setFromAxisAngle(rollAxis, moveDist / 0.85);
          ball.quaternion.premultiply(deltaQuat);
        }

        // Check hazard crash
        const ballBox = new THREE.Box3().setFromObject(ball);
        ballBox.expandByScalar(-0.24);
        for (const tile of tiles) {
          for (const obs of tile.obstacles) {
            if (ballBox.intersectsBox(obs.box)) {
              gameOver();
              return;
            }
          }
        }
        if (ball.position.y < lastY - 28) {
          gameOver();
          return;
        }

        while (lastZ > ball.position.z - 360) {
          makeTile(12, 40, -0.11, 0, Math.abs(lastZ) > 80);
        }
        while (tiles.length > 0 && tiles[0].z > ball.position.z + 65) {
          const old = tiles.shift();
          scene.remove(old.mesh);
          scene.remove(old.edges);
          old.obstacles.forEach(o => scene.remove(o.mesh));
        }

        const curScore = Math.floor(Math.abs(ball.position.z) / 5);
        scoreText.innerText = curScore;

        grid.position.z = ball.position.z - 150;
        cityGroup.position.z = ball.position.z * 0.7;
      }

      camera.position.x += (ball.position.x * 0.82 - camera.position.x) * 0.14;
      camera.position.y += (ball.position.y + 6.6 - camera.position.y) * 0.14;
      camera.position.z += (ball.position.z + 13.0 - camera.position.z) * 0.2;
      camera.lookAt(ball.position.clone().add(new THREE.Vector3(0, -0.5, -24)));

      renderer.render(scene, camera);
    }

    function gameOver() {
      isPlaying = false;
      const finalScore = Math.floor(Math.abs(ball.position.z) / 5);
      if (finalScore > highScore) {
        highScore = finalScore;
        localStorage.setItem('slope_standalone_best', highScore);
        bestText.innerText = highScore;
      }
      overlay.style.display = 'flex';
      startBtn.innerText = 'PLAY AGAIN (SCORE: ' + finalScore + ')';
    }

    requestAnimationFrame(animate);
